	public void populateLTBowlerSpeed(PrintWriter print_writer, String viz_scene, int whichInning, int playerId,
			MatchAllData match, String broadcaster, int whichside) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: BowlerStats's inning is null";
		} else {
			int total_inn = 0, sum = 0;

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningStatus() != null) {
					total_inn = total_inn + 1;
				}
			}

			if (total_inn > 0 && whichInning > total_inn) {
				whichInning = total_inn;
			}
//			print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Select*FUNCTION*Omo*vis_con SET 0 \0");
//			print_writer.println("-1 RENDERER*TREE*$LT$All$BaseAll$Select*FUNCTION*Omo*vis_con SET 0 \0");
//			print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Select*FUNCTION*Omo*vis_con SET 15 \0");

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side" + whichside
							+ "$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET " + logo_path
							+ inn.getBowling_team().getTeamBadge() + "\0");
					print_writer.println("-1 RENDERER*TREE*$LT$ALL_LT_LOGOGRP$Side" + whichside
							+ "$Select$OneTeam$LTLogoGRP$LogoIn$LLC_LogoGrp$img_Badges_Shadow*TEXTURE*IMAGE SET "
							+ Toutline_color_path + inn.getBowling_team().getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*TREE*$LT$BaseAll$Side" + whichside
							+ "$Select$OneTeam$LTLogoGRP$LogoIn$img_Base1*TEXTURE*IMAGE SET " + base_path + "1/"
							+ inn.getBowling_team().getTeamBadge() + " \0");
					print_writer.println("-1 RENDERER*TREE*$LT$BaseAll$Side" + whichside
							+ "$Select$OneTeam$LTLogoGRP$LogoIn$img_Base2*TEXTURE*IMAGE SET " + base_path + "2/"
							+ inn.getBowling_team().getTeamBadge() + " \0");
					print_writer.println("-1 RENDERER*TREE*$LT$All$BaseAll$Side" + whichside
							+ "$Select$OneTeam$TopBand$img_Base2*TEXTURE*IMAGE SET " + base_path + "2/"
							+ inn.getBowling_team().getTeamBadge() + " \0");

					for (BowlingCard boc : inn.getBowlingCard()) {
						if (boc.getPlayerId() == playerId) {

							if (boc.getPlayer().getSurname() != null) {
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$AvgSpeed$TopGrp$HeaderGrp$img_Text2$txt_Header1*GEOM*TEXT SET "
										+ boc.getPlayer().getFirstname() + "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$AvgSpeed$TopGrp$HeaderGrp$img_Text2$txt_Header2*GEOM*TEXT SET "
										+ boc.getPlayer().getSurname() + "\0");
							} else {
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$AvgSpeed$TopGrp$HeaderGrp$img_Text2$txt_Header1*GEOM*TEXT SET " + ""
										+ "\0");
								print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
										+ "$Select$AvgSpeed$TopGrp$HeaderGrp$img_Text2$txt_Header2*GEOM*TEXT SET "
										+ boc.getPlayer().getFirstname() + "\0");
							}

							print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
									+ "$Select$AvgSpeed$BottomGrp$RestDataGrp$img_Text2$RestData$Data$1$img_Text2$txt_Data2A*GEOM*TEXT SET "
									+ CricketFunctions.speedData(match, whichInning, playerId)
											.get(CricketFunctions.speedData(match, whichInning, playerId).size() - 1)
									+ " Kph" + "\0");
							print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
									+ "$Select$AvgSpeed$BottomGrp$RestDataGrp$img_Text2$RestData$Data$2$img_Text2$txt_Data2A*GEOM*TEXT SET "
									+ CricketFunctions.speedData(match, whichInning, playerId).get(0) + " Kph" + "\0");

							for (int i = 0; i < CricketFunctions.speedData(match, whichInning, playerId).size(); i++) {
								sum += CricketFunctions.speedData(match, whichInning, playerId).get(i);

							}

							print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
									+ "$Select$AvgSpeed$BottomGrp$RestDataGrp$img_Text2$RestData$Data$3$img_Text2$txt_Data3A*GEOM*TEXT SET "
									+ "AVERAGE BALL" + "\0");
							print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
									+ "$Select$AvgSpeed$BottomGrp$RestDataGrp$img_Text2$RestData$Data$3$img_Text2$txt_Data2A*GEOM*TEXT SET "
									+ (sum / CricketFunctions.speedData(match, whichInning, playerId).size()) + " Kph"
									+ "\0");
						}
					}
				}
			}
//			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.jpg LT$LTLogoIn 2.000 LT$LTBaseIn 2.000 LT$LTDataIn 2.000\0");
			TimeUnit.MILLISECONDS.sleep(100);
		}
	}

