			print_writer.println("-1 RENDERER*TREE*$LT$All$DataAll$Side" + whichside
					+ "$Select$NextToBat$TopGrp$HeaderGrp$img_Text1$txt_Header1*GEOM*TEXT SET " + "NEXT TO BAT" + "\0");

