	public void populateLtMatchPromo(PrintWriter print_writer, String viz_scene, int match_number, List<Team> team,
			List<Fixture> fix, MatchAllData match, String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: MatchId's inning is null";
		} else {
			print_writer.println(
					"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01" + " SET " + " " + "\0");

			for (Team TM : team) {
				if (fix.get(match_number - 1).getHometeamid() == TM.getTeamId()) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "lgHomeTeamLogo"
							+ " SET " + "IMAGE*/Default/Nepal_T20/Logos/" + TM.getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHomeTeamFirstName" + " SET " + TM.getTeamName2().toUpperCase() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHomeTeamLastName" + " SET " + TM.getTeamName3().toUpperCase() + "\0");
				}
				if (fix.get(match_number - 1).getAwayteamid() == TM.getTeamId()) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "lgAwayTeamLogo"
							+ " SET " + "IMAGE*/Default/Nepal_T20/Logos/" + TM.getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tAwayTeamFirstName" + " SET " + TM.getTeamName2().toUpperCase() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tAwayTeamLastName" + " SET " + TM.getTeamName3().toUpperCase() + "\0");
				}
			}
			Calendar cal = Calendar.getInstance();
			cal.add(Calendar.DATE, +1);
			if (fix.get(match_number - 1).getDate()
					.equalsIgnoreCase(new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime()))) {

				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ "LIVE FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01" + " SET "
						+ "TOMORROW - " + fix.get(match_number - 1).getMatchfilename().toUpperCase() + "\0");

			} else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ "LIVE FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01" + " SET "
						+ "UP NEXT - " + fix.get(match_number - 1).getMatchfilename().toUpperCase() + "\0");

			}
//			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.jpg In 1.120 \0");
			TimeUnit.SECONDS.sleep(2);
		}
	}

