//		print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side" + whichside + "$PointsTable$LogoGrp1$LogoOut$img_Badges*TEXTURE*IMAGE SET " 
//				+ text_path + "2/" + "GEN" + "\0");

