	public void checkConditionFFNoChangeOn(PrintWriter print_writer, String whatToProcess, List<Scene> scenes,
			String valueToProcess) throws InterruptedException {
		scenes.get(2).setScene_path(valueToProcess.split(",")[0]);
		scenes.get(2).scene_load(print_writer, broadcaster);
		infobar.setFf_loaded(false);
	}

	public void PerformerPreview(PrintWriter print_writer, String viz_scene, int which_side, String which_graphic)
			throws InterruptedException {
		if (which_side == 1) {
			switch (which_graphic) {
			case "BAT_PERFORMER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BattingCard$In 2.540 anim_FullFrames$In_Out$Main$BatExtraData$BatPerformer$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT_PARTNERSHIP":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BattingCard$In 2.540 anim_FullFrames$In_Out$Main$BatExtraData$BatPartnership$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BALL_PERFORMER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BowlingCard$In 2.540 anim_FullFrames$In_Out$Main$BowlingExtraData$BallPerformer$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			}
		} else if (which_side == 2) {
			String p_graphic = "", n_graphic = "", BatOrBall = "";
			switch (which_graphic_on_screen) {
			case "BATBALLSUMMARY_SCORECARD_PERFORMER":
				p_graphic = "Change$Main$BatExtraData$BatPerformer$Change_Out 1.060";
				break;
			case "BATBALLSUMMARY_SCORECARD_PARTNERSHIP":
				p_graphic = "Change$Main$BatExtraData$BatPartnership$Change_Out 1.060";
				break;
			case "BATBALLSUMMARY_BOWLINGCARD_PERFORMER":
				p_graphic = "Change$Main$BowlingExtraData$BallPerformer$Change_Out 1.060";
				break;
			}

			switch (which_graphic) {
			case "BAT_PERFORMER":
				BatOrBall = "anim_FullFrames$In_Out$Main$BattingCard$In 2.500";
				n_graphic = "Change$Main$BatExtraData$BatPerformer$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT_PARTNERSHIP":
				BatOrBall = "anim_FullFrames$In_Out$Main$BattingCard$In 2.500";
				n_graphic = "Change$Main$BatExtraData$BatPartnership$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BALL_PERFORMER":
				BatOrBall = "anim_FullFrames$In_Out$Main$BowlingCard$In 2.500";
				n_graphic = "Change$Main$BowlingExtraData$BallPartnership$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			}

			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
					+ " C:/Temp/Preview.png anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 " + ""
					+ BatOrBall + p_graphic + " " + n_graphic + " anim_FullFrames$In_Out$Footer$In 2.560 \0");
			TimeUnit.MILLISECONDS.sleep(500);
		}
	}

	public void populateInfobarPlayerStats(Infobar infobar, boolean is_this_updating, PrintWriter printWriter,
			int teamId, int playerId, String playerType, String Profile, MatchAllData match, Statistics stats,
			String broadcaster) {
		Player plyr = getPlayerFromMatchData(stats.getPlayerID(), match);
		if (plyr.getTeamId() == match.getSetup().getHomeTeamId()) {
			System.out.println("HOME : " + plyr.getFirstname());
		} else {
			System.out.println("Away : " + plyr.getFirstname());
		}
		switch (playerType.toUpperCase()) {
		case "BAT":
			if (Profile.toUpperCase().equalsIgnoreCase(CricketUtil.DT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.IT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.ODI)
					|| Profile.toUpperCase().equalsIgnoreCase("LLCS1")) {
				System.out
						.println(" stats.getMatches() : " + stats.getMatches() + " stats.Runs() : " + stats.getRuns());

			}
			break;
		}
	}

